  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.box.value =
        this.plot.value === null ? this.box.value : measureBox(this.plot.value, this.box.value)
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.plot.value]) if (element) resize?.observe(element)
    this.release1 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.reading.value.subscribe((now) => {
      this.position.value = now
    })
  }

  private effect3(): void {
    this.warningLog.value.log(this.model.value.warnings, (message) => devWarning(true, message))
  }

  private effect4(): void {
    this.brush.value.subscribe(() => {
      this.brushed.value = this.brush.value.state()
    })
  }

  private effect5(): void {
    this.release5?.()
    this.sync.value.join(this.model.value.syncGroup, this.plot.value)
    this.release5 = () => {
      this.sync.value.leave()
    }
  }

  private effect6(): void {
    this.reading.value.subscribe((now, was) => {
      if (now.index !== was.index) this.send.value(now.index)
    })
  }

  private effect7(): void {
    this.release7?.()
    const ran =
      !this.$.listening(this.onSelect, 'onSelect') &&
      !this.model.value.legend &&
      !this.model.value.brushOn
        ? () => {}
        : agentMember({
            member: 'LineChart',
            element: () => this.frame.value,
            state: () => ({
              items: this.$.listening(this.onSelect, 'onSelect')
                ? chartMarks(this.marks.value, this.reading.value)
                : [],
              position: chartPosition(this.marks.value, this.reading.value),
              count: this.walk.value.count,
              series: chartSeries(this.frame.value, chartLegend.key, this.model.value.painted),
              hidden: chartHiddenSeries(
                this.frame.value,
                chartLegend.key,
                this.model.value.painted,
              ),
              'range-start': chartRange(this.marks.value, this.brush.value).start,
              'range-end': chartRange(this.marks.value, this.brush.value).end,
            }),
            actions: {
              read: {
                argument: 'number',
                run: (value) => readChartPosition(this.marks.value, value, this.reading.value),
              },
              choose: {
                argument: 'id',
                among: 'items',
                run: (value) =>
                  chooseChartMark(this.marks.value, value, this.reading.value, this.activate.value),
              },
              toggle: {
                argument: 'id',
                among: 'series',
                run: (value) =>
                  toggleChartSeries(
                    this.frame.value,
                    chartLegend.key,
                    this.model.value.painted,
                    value,
                  ),
              },
              brush: {
                argument: 'number',
                run: (value) =>
                  (() => {
                    this.updateBrush.value()
                    brushChartRange(this.marks.value, value, this.brush.value, this.reading.value)
                  })(),
              },
            },
          })
    this.release7 = () => {
      ran()
    }
  }
